const https = require('https');

// Your Neon connection string
const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

async function fetchFromNeon() {
  return new Promise((resolve, reject) => {
    try {
      // 1. Strictly parse the injected vendor ID variable (No Fallback)
      let vendorIdInput = typeof $vendor_id !== 'undefined' ? String($vendor_id) : '';
      const match = vendorIdInput.match(/VEND\d+/i);

      // If no valid vendor ID is found in the input, abort immediately
      if (!match) {
          return resolve(JSON.stringify({ 
              error: "Missing or invalid vendor ID", 
              details: "The $vendor_id variable was empty or did not contain a valid ID like 'VEND123'." 
          }, null, 2));
      }

      const vendorId = match[0].toUpperCase();

      // 2. Prepare the payload
      const postData = JSON.stringify({
        query: "SELECT * FROM vendor_audits WHERE vendorid = $1 LIMIT 1;",
        params: [vendorId]
      });

      // 3. Configure the HTTPS request
      const options = {
        hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
        port: 443,
        path: '/sql',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Neon-Connection-String': connectionString,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      // 4. Execute the request
      const req = https.request(options, (res) => {
        let data = '';

        // Accumulate data chunks as they arrive
        res.on('data', (chunk) => {
          data += chunk;
        });

        // When the response is fully received
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try {
              const parsedData = JSON.parse(data);
              // Handle Neon's specific response structure
              const rows = Array.isArray(parsedData) ? parsedData : parsedData.rows;
              const resultObj = (rows && rows.length > 0) ? rows[0] : { error: `No records found in database for ${vendorId}` };
              // Add this right before the `resolve(JSON.stringify(resultObj...` line in the custom function
            if (resultObj.riskrating) {
                resultObj.riskLevel = resultObj.riskrating.toUpperCase();
            }
              resolve(JSON.stringify(resultObj, null, 2));
            } catch (e) {
              resolve(JSON.stringify({ error: "Failed to parse JSON response", details: e.message }));
            }
          } else {
            resolve(JSON.stringify({ error: `Neon HTTP API Error: ${res.statusCode}`, details: data }));
          }
        });
      });

      // Handle network-level errors
      req.on('error', (e) => {
        resolve(JSON.stringify({ 
            error_string: "HTTPS Request failed", 
            message: e.message 
        }, null, 2));
      });

      // Send the payload and finalize the request
      req.write(postData);
      req.end();

    } catch (err) {
      resolve(JSON.stringify({
        error_string: String(err),
        message: err.message || "No message",
        name: err.name || "Unknown Error"
      }, null, 2));
    }
  });
}

return await fetchFromNeon();

