/*
 * Risk Scoring Calculator
 * Deterministic weighted formula for audit risk scoring
 * Weights: CRITICAL=30, HIGH=20, MEDIUM=10, LOW=5
 * Threshold: >= 70 requires human review
 */

const weights = { critical: 30, high: 20, medium: 10, low: 5 };
let counts = { critical: 0, high: 0, medium: 0, low: 0 };

try {
    // Try to parse the verified flags from the previous phase
    const text = $verifiedFlags || '';

    // Try JSON parse first
    let parsed;
    try {
        // Find JSON in the text
        const jsonMatch = text.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
            parsed = JSON.parse(jsonMatch[0]);
        }
    } catch(e) {
        parsed = null;
    }

    if (parsed && parsed.summary) {
        // Use the summary counts from the verifier
        counts.critical = parsed.summary.critical || 0;
        counts.high = parsed.summary.high || 0;
        counts.medium = parsed.summary.medium || 0;
        counts.low = parsed.summary.low || 0;
    } else if (parsed && parsed.verifiedFlags && Array.isArray(parsed.verifiedFlags)) {
        // Count from array of flags
        for (const flag of parsed.verifiedFlags) {
            const sev = (flag.severity || flag.Severity || 'medium').toLowerCase();
            if (counts.hasOwnProperty(sev)) counts[sev]++;
        }
    } else {
        // Fallback: count severity keywords in text
        counts.critical = (text.match(/\bcritical\b/gi) || []).length;
        counts.high = (text.match(/\bhigh\b/gi) || []).length;
        counts.medium = (text.match(/\bmedium\b/gi) || []).length;
        counts.low = (text.match(/\blow\b/gi) || []).length;
        // Avoid over-counting by capping
        counts.critical = Math.min(counts.critical, 10);
        counts.high = Math.min(counts.high, 10);
        counts.medium = Math.min(counts.medium, 10);
        counts.low = Math.min(counts.low, 10);
    }
} catch(e) {
    // If everything fails, default to medium risk
    counts.medium = 3;
}

// Calculate weighted score
let score = counts.critical * weights.critical +
            counts.high * weights.high +
            counts.medium * weights.medium +
            counts.low * weights.low;

// Cap at 100
score = Math.min(score, 100);

// Determine risk level
let level;
if (score >= 70) level = 'CRITICAL';
else if (score >= 50) level = 'HIGH';
else if (score >= 30) level = 'MEDIUM';
else level = 'LOW';

const result = {
    riskScore: score,
    riskLevel: level,
    breakdown: counts,
    weights: weights,
    threshold: 70,
    requiresHumanReview: score >= 70,
    routing: score >= 70 ? 'ESCALATE_TO_HUMAN' : 'AUTO_APPROVE'
};

return JSON.stringify(result, null, 2);

